class Solution:
    def findBalancedIndex(self, nums):
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]
        CAP = 2 * 10 ** 14
        suf = [1] * (n + 1)
        for i in range(n - 1, -1, -1):
            p = suf[i + 1] * nums[i]
            suf[i] = p if p <= CAP else CAP + 1
        for i in range(n):
            if pref[i] == suf[i + 1]:
                return i
        return -1

