class Solution {
public:
    int findBalancedIndex(vector<int>& nums) {
        int n = nums.size();
        vector<long long> pref(n + 1, 0), suf(n + 1, 1);
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        const long long CAP = 200000000000000LL;
        for (int i = n - 1; i >= 0; i--) {
            long long p = suf[i + 1] * nums[i];
            suf[i] = p <= CAP ? p : CAP + 1;
        }
        for (int i = 0; i < n; i++)
            if (pref[i] == suf[i + 1]) return i;
        return -1;
    }
};

